def main():
    project_root = os.getcwd()
    print(f"[patch] プロジェクトルート: {project_root}")
    if not os.path.isdir(os.path.join(project_root, "apps")):
        print("[patch][警告] 'apps' フォルダが見つかりません。machcoreルートで実行してください。")
        sys.exit(1)

    compressed = base64.b64decode(_PAYLOAD_B64)
    raw = gzip.decompress(compressed)
    payload = json.loads(raw.decode("utf-8"))

    written = []
    for rel_path, content in payload["write"].items():
        abs_path = os.path.join(project_root, rel_path)
        os.makedirs(os.path.dirname(abs_path), exist_ok=True)
        with open(abs_path, "w", encoding="utf-8") as f:
            f.write(content)
        written.append(rel_path)

    print(f"[patch] 更新ファイル書き込み: {len(written)} 件")
    for p in written:
        print(f"  - {p}")

    self_path = os.path.abspath(__file__)
    try:
        os.remove(self_path)
        print(f"[patch] 自分自身を削除しました: {self_path}")
    except OSError as e:
        print(f"[patch][警告] 自己削除に失敗: {e}")

    print("")
    print("[patch] 完了。続けて以下を実行してください:")
    print("  cd apps/api && npx nest build && cd ../web && npx tsc --noEmit && npx next build && cd ../..")
    print("  pm2 delete machcore-web 2>/dev/null; pm2 start ecosystem.config.js --only machcore-web")
    print("  pm2 restart machcore-api")
    print('  git add -A && git commit -m "feat(i18n): mc/[mc_id]/edit ツーリング明細等を完全t()化" && git push origin main')


if __name__ == "__main__":
    main()
